arguments.command:
cd /work && python -c "
import pandas as pd,numpy as np,warnings; warnings.filterwarnings('ignore')
from pymatgen.core import Structure
from pymatgen.symmetry.analyzer import SpacegroupAnalyzer
t=pd.read_csv('cdft_piezo_d_train.csv')
for f in ['Na3SbS4','TaTl3S4','RbPbBr3','LiGeBO4','AgCN','PbS','TiS2','GeI2','Cd3AsI3','BaAuCl','KInP2S7','NaSbP2S6','Tl3AsS3','SbN','KYSn','AuO2F','GeSe2','Ta3SeI7','Al2CdSe4','ZnSiN2','RbCaCl3','SrHfO3','TlCdF3','TiPbO3','CdSnP2','AlPO4']:
    for i,r in t[t.formula==f].iterrows():
        s=Structure.from_str(r.poscar,fmt='poscar'); sga=SpacegroupAnalyzer(s,symprec=0.1)
        print(f.ljust(10), sga.get_space_group_symbol().ljust(10), sga.get_point_group_symbol().ljust(6), len(s), round(s.volume/len(s),1), round(r.d_ij,1))
"

cd /work && python -c "
import pandas as pd,numpy as np,warnings; warnings.filterwarnings('ignore')
from pymatgen.core import Structure
from pymatgen.symmetry.analyzer import SpacegroupAnalyzer
p=pd.read_csv('cdft_piezo_pool.csv')
for i,r in p.iterrows():
    s=Structure.from_str(r.poscar,fmt='poscar')
    o=[]
    for sp in [0.05,0.3,1.0]:
        try:
            sga=SpacegroupAnalyzer(s,symprec=sp); o.append(sga.get_point_group_symbol()+'/'+str(sga.get_space_group_number()))
        except: o.append('?')
    if o[0]!=o[2]: print(r.candidate_id, r.formula.ljust(10), o)
" 2>/dev/null

